-- UF

declare @data date

set @data = '20250101'

;with dados as (
    -- tanby nd
    select c.UFESIG, count(*) as qtde
      from TBS067 c with (nolock)
     where c.NFSDATEMI >= @data
     group by c.UFESIG

    union all

    -- best bag
    select c.UFESIG, count(*) as qtde
      from bb.SIBD2.dbo.TBS067 c with (nolock)
     where c.NFSDATEMI >= @data
     group by c.UFESIG

    union all

    -- misaspel
    select c.UFESIG
           ,count(*)
      from mi.SIBD3.dbo.TBS067 c with (nolock)
     where c.NFSDATEMI >= @data
     group by c.UFESIG

    union all

    -- papelyna
    select c.UFESIG
           ,count(*)
      from pp.SIBD.dbo.TBS067 c with (nolock)
     where c.NFSDATEMI >= @data
     group by c.UFESIG

    union all

    -- tanby cd
    select c.UFESIG collate database_default
           ,count(*)
      from cd.SIBD.dbo.TBS067 c with (nolock)
     where c.NFSDATEMI >= @data
     group by c.UFESIG

    union all

    -- tanby taubaté
    select c.UFESIG
           ,count(*)
      from tt.SIBD.dbo.TBS067 c with (nolock)
      where c.NFSDATEMI >= @data
     group by c.UFESIG

    /*union all

    -- winpack
    select c.UFESIG
           ,count(*)
      from wp.SIBD4.dbo.TBS067 c with (nolock)
     where c.NFSDATEMI >= @data
     group by c.UFESIG*/

)
select UFESIG, sum(qtde) as total
  from dados
 group by UFESIG
 order by UFESIG;

-- CFOP

select d.NFSCFOP
       ,count(*)
  from TBS0671 d with (nolock)
 inner join TBS067 c with (nolock)
       on c.NFSNUM=d.NFSNUM
 where c.NFSDATEMI >= '20230101'
 group by d.NFSCFOP

-- CFOP de saídas com descritivo

select res.CFOP
       ,(select COPDES from TBS041 cfop with (nolock) where cfop.COPTIP = 'S' and right(cfop.COPCODDDE,3) = right(res.CFOP,3))
       ,(select COPTXT from TBS041 cfop with (nolock) where cfop.COPTIP = 'S' and right(cfop.COPCODDDE,3) = right(res.CFOP,3))
  from (
         select d.NFSCFOP as CFOP
           from TBS0671 d with (nolock)
          inner join TBS067 c with (nolock)
                  on c.NFSNUM=d.NFSNUM
          where c.NFSDATEMI >= '20200101'
                and c.NFSCAN = 'N'
                and d.NFSCFOP <> ''
          group by d.NFSCFOP
       ) as res

-- CFOP de saídas com descritivo - todo o grupo

select res.CFOP
       ,(select COPDES from TBS041 cfop with (nolock) where cfop.COPTIP = 'S' and right(cfop.COPCODDDE,3) = right(res.CFOP,3))
       ,(select COPTXT from TBS041 cfop with (nolock) where cfop.COPTIP = 'S' and right(cfop.COPCODDDE,3) = right(res.CFOP,3))
  from (
         select d.NFSCFOP as CFOP
           from TBS0671 d with (nolock)
          inner join TBS067 c with (nolock)
                  on c.NFSNUM=d.NFSNUM
          where c.NFSDATEMI >= '20200101'
                and c.NFSCAN = 'N'
                and d.NFSCFOP <> ''
          group by d.NFSCFOP
         
         union
         
         -- best bag
         select d.NFSCFOP
           from bb.SIBD2.dbo.TBS0671 d with (nolock)
          inner join bb.SIBD2.dbo.TBS067 c with (nolock)
                  on c.NFSNUM=d.NFSNUM
          where c.NFSDATEMI >= '20200101'
                and c.NFSCAN = 'N'
                and d.NFSCFOP <> ''
          group by d.NFSCFOP

         union
         
         -- misaspel
         select d.NFSCFOP
           from mi.SIBD3.dbo.TBS0671 d with (nolock)
          inner join mi.SIBD3.dbo.TBS067 c with (nolock)
                  on c.NFSNUM=d.NFSNUM
          where c.NFSDATEMI >= '20200101'
                and c.NFSCAN = 'N'
                and d.NFSCFOP <> ''
          group by d.NFSCFOP

         union
         
         -- papelyna
         select d.NFSCFOP
           from pp.SIBD.dbo.TBS0671 d with (nolock)
          inner join pp.SIBD.dbo.TBS067 c with (nolock)
                  on c.NFSNUM=d.NFSNUM
          where c.NFSDATEMI >= '20200101'
                and c.NFSCAN = 'N'
                and d.NFSCFOP <> ''
          group by d.NFSCFOP

         union
         
         -- tanby cd
         select d.NFSCFOP collate database_default
           from cd.SIBD.dbo.TBS0671 d with (nolock)
          inner join cd.SIBD.dbo.TBS067 c with (nolock)
                  on c.NFSNUM=d.NFSNUM
          where c.NFSDATEMI >= '20200101'
                and c.NFSCAN = 'N'
                and d.NFSCFOP <> ''
          group by d.NFSCFOP

         union
         
         -- tanby taubaté
         select d.NFSCFOP
           from tt.SIBD.dbo.TBS0671 d with (nolock)
          inner join tt.SIBD.dbo.TBS067 c with (nolock)
                  on c.NFSNUM=d.NFSNUM
          where c.NFSDATEMI >= '20200101'
                and c.NFSCAN = 'N'
                and d.NFSCFOP <> ''
          group by d.NFSCFOP
       ) as res
 order by res.CFOP

-- CST/ICMS

select right(Ltrim(rtrim(d.NFSCST)),2)
       ,count(*) as n
  from TBS0671 d with (nolock)
 inner join TBS067 c with (nolock)
         on c.NFSNUM=d.NFSNUM
 where c.NFSDATEMI >= '20150101'
       and Len(Ltrim(d.NFSCST)) = 3
 group by right(Ltrim(rtrim(d.NFSCST)),2)

-- CST/ICMS com descritivo

select res.CST
       ,(select cst.CSTDES from TBS039 cst with (nolock) where cst.CSTTAB = 'B' and cst.CSTCOD=right(Ltrim(rtrim(res.CST)),2)) as descricao
       ,res.contador
  from (
         select right(Ltrim(rtrim(d.NFSCST)),2) as CST
                ,count(*) as contador
           from TBS0671 d with (nolock)
          inner join TBS067 c with (nolock)
                  on c.NFSNUM=d.NFSNUM
          where c.NFSDATEMI >= '20150101'
                and Len(Ltrim(d.NFSCST)) = 3
          group by right(Ltrim(rtrim(d.NFSCST)),2)
       ) as res

-- CST/ICMS com descritivo e percentual

with cte_base as (
   select right(ltrim(rtrim(d.NFSCST)),2) as CST
          ,count(*) as contador
     from TBS0671 d with (nolock)
    inner join TBS067 c with (nolock)
            on c.NFSNUM = d.NFSNUM
    where c.NFSDATEMI >= '20150101'
          and len(ltrim(d.NFSCST)) = 3
    group by right(ltrim(rtrim(d.NFSCST)),2)
),
cte_total as (
   select sum(contador) as total_geral from cte_base
)
select res.CST
       ,(select cst.CSTDES 
           from TBS039 cst with (nolock) 
          where cst.CSTTAB = 'B' 
                and cst.CSTCOD = res.CST) as descricao
       ,res.contador
       ,cast(1.0 * res.contador / total.total_geral * 100 as decimal(5,2)) as percentual
  from cte_base res
 cross join cte_total total
 order by percentual desc;


-- CST/ICMS específico

select d.NFSNUM
       ,c.NFSDATEMI
  from TBS0671 d with (nolock)
 inner join TBS067 c with (nolock)
       on c.NFSNUM=d.NFSNUM
 where c.NFSDATEMI >= '20150101'
       and c.NFSCAN = 'N'
       and Len(Ltrim(d.NFSCST)) = 3
       and right(Ltrim(rtrim(d.NFSCST)),2) = '20'

-- regra do ICMS

select d.NFSROPREG
       ,count(*) as contador
  from TBS0671 d with (nolock)
 inner join TBS067 c with (nolock)
         on c.NFSNUM=d.NFSNUM
 where c.NFSDATEMI >= '20150101'
       and d.NFSROPREG > 0
 group by d.NFSROPREG;

-- regra do ICMS e percentual

with cte_base as (
   select d.NFSROPREG as regra
          ,count(*) as contador
     from TBS0671 d with (nolock)
    inner join TBS067 c with (nolock)
            on c.NFSNUM = d.NFSNUM
    where c.NFSDATEMI >= '20150101'
          and d.NFSROPREG > 0
    group by d.NFSROPREG
),
cte_total as (
   select sum(contador) as total_geral from cte_base
)
select res.regra
       ,res.contador
       ,cast(1.0 * res.contador / total.total_geral * 100 as decimal(5,2)) as percentual
       ,(select r.ROPTIPOPE
           from TBS110 r with (nolock) 
          where r.ROPREG = res.regra) as operacao
       ,(select r.ROPDES
           from TBS110 r with (nolock) 
          where r.ROPREG = res.regra) as desc_operacao
       ,(select r.ROPNATOPE
           from TBS110 r with (nolock) 
          where r.ROPREG = res.regra) as natureza
       ,(select r.ROPTIPNF
           from TBS110 r with (nolock) 
          where r.ROPREG = res.regra) as tipo_nf
  from cte_base res
 cross join cte_total total
 order by percentual desc;

