-- pivot

with dados as (
    select 
        periodo,
        isnull(sum(case when empresa = 'tanby_nd' then qtd end), 0) as tanby_nd,
        isnull(sum(case when empresa = 'best_bag' then qtd end), 0) as best_bag,
        isnull(sum(case when empresa = 'misaspel' then qtd end), 0) as misaspel,
        isnull(sum(case when empresa = 'papelyna' then qtd end), 0) as papelyna,
        isnull(sum(case when empresa = 'tanby_taubate' then qtd end), 0) as tanby_taubate,
        isnull(sum(case when empresa = 'tanby_cd' then qtd end), 0) as tanby_cd,
        isnull(sum(case when empresa = 'winpack' then qtd end), 0) as winpack
    from (
        -- tanby nd
        select 'tanby_nd' as empresa, convert(char(6), NFSDATEMI, 112) as periodo, count(*) as qtd
          from TBS067 with (nolock)
         where NFSDATEMI >= '20230101' and NFSDESICMS = 'S'
         group by convert(char(6), NFSDATEMI, 112)

        union all

        -- best bag
        select 'best_bag', convert(char(6), NFSDATEMI, 112), count(*)
          from bb.SIBD2.dbo.TBS067 with (nolock)
         where NFSDATEMI >= '20230101' and NFSDESICMS = 'S'
         group by convert(char(6), NFSDATEMI, 112)

        union all

        -- misaspel
        select 'misaspel', convert(char(6), NFSDATEMI, 112), count(*)
          from mi.SIBD3.dbo.TBS067 with (nolock)
         where NFSDATEMI >= '20230101' and NFSDESICMS = 'S'
         group by convert(char(6), NFSDATEMI, 112)

        union all

        -- papelyna
        select 'papelyna', convert(char(6), NFSDATEMI, 112), count(*)
          from pp.SIBD.dbo.TBS067 with (nolock)
         where NFSDATEMI >= '20230101' and NFSDESICMS = 'S'
         group by convert(char(6), NFSDATEMI, 112)

        union all

        -- tanby taubaté
        select 'tanby_taubate', convert(char(6), NFSDATEMI, 112), count(*)
          from tt.SIBD.dbo.TBS067 with (nolock)
         where NFSDATEMI >= '20230101' and NFSDESICMS = 'S'
         group by convert(char(6), NFSDATEMI, 112)

        union all

        -- tanby cd
        select 'tanby_cd', convert(char(6), NFSDATEMI, 112), count(*)
          from cd.SIBD.dbo.TBS067 with (nolock)
         where NFSDATEMI >= '20230101' and NFSDESICMS = 'S'
         group by convert(char(6), NFSDATEMI, 112)

        union all

        -- winpack
        select 'winpack', convert(char(6), NFSDATEMI, 112), count(*)
          from wp.SIBD4.dbo.TBS067 with (nolock)
         where NFSDATEMI >= '20230101' and NFSDESICMS = 'S'
         group by convert(char(6), NFSDATEMI, 112)
    ) as origem
    group by periodo
)
select 
    periodo,
    tanby_nd, best_bag, misaspel, papelyna, tanby_taubate, tanby_cd, winpack,
    (tanby_nd + best_bag + misaspel + papelyna + tanby_taubate + tanby_cd + winpack) as total_periodo
from dados

union all

-- Linha de totais gerais
select 
    'TOTAL',
    sum(tanby_nd),
    sum(best_bag),
    sum(misaspel),
    sum(papelyna),
    sum(tanby_taubate),
    sum(tanby_cd),
    sum(winpack),
    sum(tanby_nd + best_bag + misaspel + papelyna + tanby_taubate + tanby_cd + winpack)
from dados

order by periodo;

