-- função para leitura dos números romanos

CREATE FUNCTION dbo.fn_RomanoParaInteiro (@romano VARCHAR(10))
RETURNS INT
AS
BEGIN
    DECLARE @resultado INT;
    SET @resultado = CASE UPPER(LTRIM(RTRIM(@romano)))
        WHEN 'I' THEN 1 WHEN 'II' THEN 2 WHEN 'III' THEN 3 WHEN 'IV' THEN 4
        WHEN 'V' THEN 5 WHEN 'VI' THEN 6 WHEN 'VII' THEN 7 WHEN 'VIII' THEN 8
        WHEN 'IX' THEN 9 WHEN 'X' THEN 10 WHEN 'XI' THEN 11 WHEN 'XII' THEN 12
        WHEN 'XIII' THEN 13 WHEN 'XIV' THEN 14 WHEN 'XV' THEN 15
        WHEN 'XVI' THEN 16 WHEN 'XVII' THEN 17 WHEN 'XVIII' THEN 18
        WHEN 'XIX' THEN 19 WHEN 'XX' THEN 20
        ELSE NULL END;
    RETURN @resultado;
END;
