-- 200010, sem anexo, 100
-- 200011, 6, 100

-- contagem de emissão de notas fiscais

select sum(case when SNESER = 1 AND LEN(ENFCNPJCPF) = 14 THEN 1 ELSE 0 END) AS CNPJ_serie_1
	     ,SUM(case when SNESER = 1 AND LEN(ENFCNPJCPF) = 11 THEN 1 ELSE 0 END) AS CPF_serie_1
       ,SUM(case when SNESER = 1 THEN 1 ELSE 0 END) AS NORMAL
       ,SUM(case when SNESER = 3 AND LEN(ENFCNPJCPF) = 14 THEN 1 ELSE 0 END) AS CNPJ_serie_3
	     ,SUM(case when SNESER = 3 AND LEN(ENFCNPJCPF) = 11 THEN 1 ELSE 0 END) AS CPF_serie_3
	     ,SUM(case when SNESER = 3 THEN 1 ELSE 0 END) AS cupom_fiscal
	     ,SUM(case when SNESER = 2 THEN 1 ELSE 0 END) AS transferencia
       ,SUM(case when SNESER in (1,2,3) THEN 1 ELSE 0 END) AS qtde_total
FROM TBS080 WITH (NOLOCK)
WHERE ENFSIT = 6
  AND ENFDATEMI BETWEEN '20251001' AND '20251031'
       and ENFFINEMI = 1
       and ENFTIPDOC = 1

exec sp_help TBS159

