-- Exemplo 1 — Produto com CEST incompatível com NCM

SELECT p.PROCOD, p.PROCLAFIS, p.PROCEST
FROM TBS010 p
 right JOIN TBS1541 r
    ON r.CESTMVACOD = p.PROCEST
   AND p.PROCLAFIS Like r.CESTMVANCM
WHERE r.CESTMVANCM IS NULL

-- Exemplo 2 — Produto sujeito a ST na UF mas sem CEST

SELECT p.PROCOD, p.PRODES, p.PROCEST
FROM TBS010 p with (nolock)
Left JOIN TBS154 c with (nolock)
ON c.CESTMVACOD = p.PROCEST
WHERE Len(p.PROCEST) = 7 and c.CESTMVACOD is null and c.CESTUFSP IS NOT NULL
  AND p.PROCEST IS NULL

-- produtos sem ST e com CEST cadastrado

select p.PROCOD
       ,p.PRODES
       ,p.PROCLAFIS
       ,p.PROCEST
       ,p.PROSTBA
       ,p.PROSTBB
  from TBS010 p with (nolock)
 where p.PROSTBB not in('10','30','60','70')
       and p.PROCEST <> ''

-- produtos com ST indevidos

select p.PROCOD
       ,p.PRODES
       ,p.PROCLAFIS
       ,p.PROCEST
       ,p.PROSTBA
       ,p.PROSTBB
       ,p.PROALIICMSINT
       ,p.TGZCOD
       ,p.PROUVDDAT
  from TBS010 p with (nolock)
 where p.PROSTBB in('10','30','60','70')
       and p.PROCEST <> ''
       and not exists (select 1 from TBS1541 cn with (nolock) where Left(cn.CESTMVACOD,3) = Left(p.PROCEST,3))



select *
  from MSL004 with (nolock)

BEGIN TRAN;

UPDATE p
SET p.PROCEST = ''
    ,p.PROSTBB = '00'
    ,p.TGZCOD = 5
FROM TBS010 p
WHERE p.PROSTBB IN ('10','30','60','70')
  AND p.PROCEST <> ''
  AND NOT EXISTS (
        SELECT 1
        FROM TBS1541 cn
        WHERE LEFT(cn.CESTMVACOD,3) = LEFT(p.PROCEST,3)
  );

-- valida
SELECT @@ROWCOUNT;

-- se estiver ok:
COMMIT;

-- se der ruim:
-- ROLLBACK;

-- produtos com CEST/ST, mas ST não configurado no produto

select p.PROCOD
       ,p.PRODES
       ,p.PROCLAFIS
       ,p.PROCEST
       ,p.PROSTBA
       ,p.PROSTBB
       ,p.PROALIICMSINT
       ,p.TGZCOD
       ,p.PROUVDDAT
  from TBS010 p with (nolock)
 where p.PROSTBB not in('10','30','60','70')
       and p.PROCEST <> ''
       and exists (select 1 from TBS1541 cn with (nolock) where Left(cn.CESTMVACOD,3) = Left(p.PROCEST,3))

-- produtos com ST

select p.PROCOD
       ,p.PRODES
       ,p.PROCLAFIS
       ,p.PROCEST
       ,p.PROSTBA
       ,p.PROSTBB
       ,p.PROALIICMSINT
       ,p.TGZCOD
       ,p.PROUVDDAT
  from TBS010 p with (nolock)
 where p.PROSTBB in('10','30','60','70')
       and p.PROCEST <> ''
       and exists (select 1 from TBS1541 cn with (nolock) where Left(cn.CESTMVACOD,3) = Left(p.PROCEST,3))

-- CEST inexistentes na tabela CEST ST

select p.PROCOD
       ,p.PRODES
       ,p.PROCLAFIS
       ,p.PROCEST
       ,p.PROSTBA
       ,p.PROSTBB
       ,p.PROALIICMSINT
       ,p.TGZCOD
       ,p.PROUVDDAT
  from TBS010 p with (nolock)
 where p.PROSTBB in('10','30','60','70')
       and p.PROCEST <> ''
       and not exists (select 1 from TBS1541 cn with (nolock) where cn.CESTMVACOD = p.PROCEST)

select p.PROCOD
       ,p.PRODES
       ,p.PROCLAFIS
       ,p.PROCEST
       ,p.PROSTBA
       ,p.PROSTBB
       ,p.PROALIICMSINT
       ,p.TGZCOD
       ,p.PROUVDDAT
  from TBS010 p with (nolock)
 where p.PROSTBB in('10','30','60','70')
       and p.PROCEST <> ''
       and not exists (select 1 from TBS1541 cn with (nolock) where Left(cn.CESTMVANCM,3) = Left(p.PROCLAFIS,3))

select p.PROCOD
       ,p.PRODES
       ,p.PROCLAFIS
       ,p.PROCEST
       ,p.PROSTBA
       ,p.PROSTBB
       ,p.PROALIICMSINT
       ,p.TGZCOD
       ,p.PROUVDDAT
       ,cn.CESTMVANCM
       ,cn.CESTMVACOD
  from TBS010 p with (nolock)
 inner join TBS1541 cn with (nolock)
         on cn.CESTMVANCM = p.PROCLAFIS
 where p.PROSTBB in('10','30','60','70')
       and p.PROCEST <> cn.CESTMVACOD

select p.PROCOD
       ,p.PRODES
       ,p.PROCLAFIS
       ,p.PROCEST
       ,p.PROSTBA
       ,p.PROSTBB
       ,p.PROALIICMSINT
       ,p.TGZCOD
