-- última venda de um produto

-- Forma mais comum (usando ROW_NUMBER() — recomendada)

WITH UltimasVendas AS (
    SELECT *,
ROW_NUMBER() OVER (
    PARTITION BY codigoProduto
    ORDER BY data DESC, hora DESC, numeroDocumento DESC
) AS rn
    FROM DWVendas
    WHERE cancelado = 'N'
)
SELECT *
FROM UltimasVendas
WHERE rn = 1;

-- Procedure otimizada (com IF)

drop procedure sp_UltimaVendaPorProduto
go

CREATE PROCEDURE sp_UltimaVendaPorProduto
(
    @DataInicial   DATE,
    @DataFinal     DATE,
    @CodigoProduto VARCHAR(15) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    -- 🔹 Caso 1: TODOS os produtos
    IF @CodigoProduto IS NULL
    BEGIN
        WITH UltimasVendas AS (
            SELECT *,
                   ROW_NUMBER() OVER (
                       PARTITION BY codigoProduto
                       ORDER BY data DESC, hora DESC, numeroDocumento DESC
                   ) AS rn
            FROM DWVendas with (nolock)
            WHERE cancelado = 'N'
              AND data BETWEEN @DataInicial AND @DataFinal
        )
        SELECT *
        FROM UltimasVendas
        WHERE rn = 1;
    END

    -- 🔹 Caso 2: PRODUTO específico (usa índice melhor)
    ELSE
    BEGIN
        WITH UltimasVendas AS (
            SELECT *,
                   ROW_NUMBER() OVER (
                       PARTITION BY codigoProduto
                       ORDER BY data DESC, hora DESC, numeroDocumento DESC
                   ) AS rn
            FROM DWVendas with (nolock)
            WHERE cancelado = 'N'
              AND data BETWEEN @DataInicial AND @DataFinal
              AND codigoProduto = @CodigoProduto
        )
        SELECT *
        FROM UltimasVendas
        WHERE rn = 1;
    END
END;
go

EXEC sp_UltimaVendaPorProduto 
    @DataInicial = '2015-01-01',
    @DataFinal   = '2026-05-25',
    @CodigoProduto = '7600185';
go

