-- Procedure otimizada (local + remoto)

CREATE PROCEDURE sp_UltimaVendaPorProdutoBMPT
(
    @DataInicial   DATE,
    @DataFinal     DATE,
    @CodigoProduto VARCHAR(15) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    -- 🔹 Caso 1: TODOS os produtos
    IF @CodigoProduto IS NULL
    BEGIN
        WITH Base AS (
            SELECT codigoProduto, [data], hora, quantidade FROM DWVendas
            WHERE cancelado = 'N'
              AND data BETWEEN @DataInicial AND @DataFinal

            UNION ALL

            SELECT codigoProduto, [data], hora, quantidade FROM bb.SIBD2.dbo.DWVendas
            WHERE cancelado = 'N'
              AND data BETWEEN @DataInicial AND @DataFinal

            UNION ALL

            SELECT codigoProduto, [data], hora, quantidade FROM mi.SIBD3.dbo.DWVendas
            WHERE cancelado = 'N'
              AND data BETWEEN @DataInicial AND @DataFinal

            UNION ALL

            SELECT codigoProduto, [data], hora, quantidade FROM pp.SIBD.dbo.DWVendas
            WHERE cancelado = 'N'
              AND data BETWEEN @DataInicial AND @DataFinal

            UNION ALL

            SELECT codigoProduto, [data], hora, quantidade FROM tt.SIBD.dbo.DWVendas
            WHERE cancelado = 'N'
              AND data BETWEEN @DataInicial AND @DataFinal
        ),
        UltimasVendas AS (
            SELECT *,
                   ROW_NUMBER() OVER (
                       PARTITION BY codigoProduto
                       ORDER BY data DESC, hora DESC
                   ) AS rn
            FROM Base
        )
        SELECT *
        FROM UltimasVendas
        WHERE rn = 1;
    END

    -- 🔹 Caso 2: PRODUTO específico (corrigido)
    ELSE
    BEGIN
        WITH Base AS (
            SELECT codigoProduto, [data], hora, quantidade FROM DWVendas
            WHERE cancelado = 'N'
              AND data BETWEEN @DataInicial AND @DataFinal
              AND codigoProduto = @CodigoProduto

            UNION ALL

            SELECT codigoProduto, [data], hora, quantidade FROM bb.SIBD2.dbo.DWVendas
            WHERE cancelado = 'N'
              AND data BETWEEN @DataInicial AND @DataFinal
              AND codigoProduto = @CodigoProduto

            UNION ALL

            SELECT codigoProduto, [data], hora, quantidade FROM mi.SIBD3.dbo.DWVendas
            WHERE cancelado = 'N'
              AND data BETWEEN @DataInicial AND @DataFinal
              AND codigoProduto = @CodigoProduto

            UNION ALL

            SELECT codigoProduto, [data], hora, quantidade FROM pp.SIBD.dbo.DWVendas
            WHERE cancelado = 'N'
              AND data BETWEEN @DataInicial AND @DataFinal
              AND codigoProduto = @CodigoProduto

            UNION ALL

            SELECT codigoProduto, [data], hora, quantidade FROM tt.SIBD.dbo.DWVendas
            WHERE cancelado = 'N'
              AND data BETWEEN @DataInicial AND @DataFinal
              AND codigoProduto = @CodigoProduto
        ),
        UltimasVendas AS (
            SELECT *,
                   ROW_NUMBER() OVER (
                       PARTITION BY codigoProduto
                       ORDER BY data DESC, hora DESC
                   ) AS rn
            FROM Base
        )
        SELECT *
        FROM UltimasVendas
        WHERE rn = 1;
    END
END;
go


EXEC sp_UltimaVendaPorProduto 
    @DataInicial = '2020-01-01',
    @DataFinal   = '2026-03-31',
    @CodigoProduto = '1640054';

