-- apuração assistida ibs/cbs

select *
  from TBS0671 i with (nolock)
 where i.NFSNUM = 396534
 order by i.NFSITE

select i.NFSNUM
       ,sum(i.NFSVALCBS)
  from TBS0671 i with (nolock)
 inner join TBS067 c with (nolock)
         on c.SNESER = i.SNESER
            and c.NFSNUM = i.NFSNUM
 where i.SNESER = 1
       and c.NFSDATEMI between '20260401' and '20260430'
       and i.NFSREDALIIBS > 0
 group by i.NFSNUM

select total_ibs
       ,total_cbs
       ,total_ibs + total_cbs
  from (
select sum(i.NFSVALIBS) as total_ibs
       ,sum(i.NFSVALCBS) as total_cbs
  from TBS0671 i with (nolock)
 inner join TBS067 c with (nolock)
         on c.SNESER = i.SNESER
            and c.NFSNUM = i.NFSNUM
 where c.NFSDATEMI between '20260401' and '20260430'
  ) t

